import{_ as i,l as s,o as e,c as l,v as t,p as n,x as o,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"类型混淆","description":"","frontmatter":{"title":"类型混淆","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/type-confusion.md","filePath":"cs/type-confusion.md","lastUpdated":1789023840000}'),h={name:"cs/type-confusion.md"};function E(_,a,u,m,A,f){const r=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="类型混淆" tabindex="-1">类型混淆 <a class="header-anchor" href="#类型混淆" aria-label="Permalink to &quot;类型混淆&quot;">​</a></h1><div class="epigraph"><p>同一段内存按两种类型解释：字段对不齐，虚表是别人的。这在 C++ 向下转型与动态类型语言的桥接里反复出现。它不是栈邻接覆盖，却同样能到达控制数据。</p><footer>—— 据 Szekeres SoK；CWE-843；对照浏览器引擎公开事故的机制陈述</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/format-string">格式化字符串</a>是 libc 解释器。缺口是<strong>对象类型</strong>：混淆后读错字段宽度，函数指针槽被当成整数写。本课讲发生条件与防御（RTTI 检查、分区 GC），不给引擎利用步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>static_cast</code> 当 <code>dynamic_cast</code> 用、union 错活跃成员、JIT 与对象模型不同步。缺口是类型安全与隔离堆（array/对象分槽）。</p><h3 id="沙箱仍要假设有洞" tabindex="-1">沙箱仍要假设有洞 <a class="header-anchor" href="#沙箱仍要假设有洞" aria-label="Permalink to &quot;沙箱仍要假设有洞&quot;">​</a></h3><p>浏览器后课把类型混淆当逃逸前奏。本课只在进程内。</p><p><span class="marginnote">CWE-843。本课禁止 PoC。Chrome 分区堆一类是工程缓解，点名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：分配成类型 A，当成 B 用。防御：checked cast、隔离、内存安全语言。指向 CET/PAC 从硬件钉控制边。</p>',12)),(e(),n(p,null,{default:o(()=>[c(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%AF%B9%E8%B1%A1%E5%BD%93%20A%20%E5%88%86%E9%85%8D%22%5D%20--%3E%20B%5B%22%E5%BD%93%20B%20%E8%A7%A3%E9%87%8A%22%5D%0A%20%20B%20--%3E%20FIELD%5B%22%E5%AD%97%E6%AE%B5%E9%94%99%E4%BD%8D%22%5D%0A%20%20FIELD%20--%3E%20VPTR%5B%22%E6%8E%A7%E5%88%B6%E6%95%B0%E6%8D%AE%E8%A2%AB%E6%94%B9%22%5D%0A%20%20DYN%5B%22dynamic_cast%20%2F%20%E6%A3%80%E6%9F%A5%22%5D%20--%3E%20STOP%5B%22%E6%8B%92%E7%BB%9D%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>类型是空间安全的逻辑层。硬件缓解下一课从影子栈与 CET 钉返回与间接跳。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不分析某 CVE。影子栈与 CET 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>格式串是解释器；类型混淆是对象模型。</li><li>错类型解释可写到函数指针。</li><li>检查转型与隔离堆是缓解。</li><li>下一课影子栈与 CET。</li><li>出处：Szekeres et al.；CWE-843。</li></ul>',8))])}const D=i(h,[["render",E]]);export{T as __pageData,D as default};
